def execute(self, tool_name, args):
    if tool_name not in self.api_specs:
        raise UnknownToolError(tool_name)                    # 1 未知工具
    if tool_name not in self.policy_card.allowed_tools:
        return error_result(TOOL_NOT_ALLOWED)                # 2 白名单
    spec = self.api_specs[tool_name]
    for req in spec.required_args:
        if req.name not in args:
            return error_result(MISSING_REQUIRED_ARG)        # 3 必填
    for arg_spec in spec.required_args + spec.optional_args:
        if arg_spec.name in args:
            ok, reason = _validate_arg(args[arg_spec.name], arg_spec)
            if not ok:
                return error_result(INVALID_FORMAT, reason=reason)  # 4 格式
    for pre in spec.preconditions:
        if not self.runtime_flags.get(pre, False):
            return error_result(PRECONDITION_NOT_MET)        # 5 前置：不计数
    self._call_counter[tool_name] = self._call_counter.get(tool_name, 0) + 1
    injected = self._pop_injection(tool_name, self._call_counter[tool_name])
    if injected:
        return error_result(injected["error_code"], injected=True)  # 6 注入
    res = self.tool_handlers[tool_name](self.db, args, copy.deepcopy(self._tool_call_log))  # 7
    if res.status == "ok":
        for post in spec.postconditions:
            self.runtime_flags[post] = True                  # 8 后置
    return res

def synthesize_trajectory(task, sandbox_builder, agent_teacher, user_teacher, config):
    for attempt in range(config.parse_max_retries + 1):
        build = sandbox_builder()   # 失败必须新沙箱
        try:
            traj, status, _ = _run_one_attempt(task, build.sandbox, ...)
            return SynthesisOutcome(status=status, trajectory=traj)
        except ParseError:
            if attempt == config.parse_max_retries:
                return SynthesisOutcome(status="parse_failed")

