LAYERS = ("L0_format", "L1_sandbox", "L2_nli", "L3_entity", "L4_rpcr", "L5_judge")

def run_verifier_funnel(task, trajectory, dependencies, config):
    failed = None
    out = {}
    for layer in LAYERS:
        if failed:
            out[layer] = {"status": "not_run", "passed": False}
            continue
        res = compute[layer](task, trajectory, dependencies, config)
        out[layer] = res
        if res["status"] != "passed":
            failed = layer
    return {"candidate_eligible": failed is None, "failed_stage": failed}

