def derive_family_id(metadata, task_type, policy_id, hidden_truth):
    if metadata.get("family_id"):
        return metadata["family_id"]
    if metadata.get("naturalization_of"):
        pair_key = metadata["naturalization_of"]          # 整段采用，不再剥后缀
    elif metadata.get("pair_id"):
        pair_key = metadata["pair_id"]
        if pair_key.endswith("__nat"):
            pair_key = pair_key[:-5]
    else:
        pair_key = ""
    if pair_key:
        return "fam_" + sha1(f"pair_id={pair_key}").hexdigest()[:16]
    persona = str(metadata.get("persona_subgroup") or "unknown")
    profile = (hidden_truth or {}).get("user_profile") or {}
    id_number = str(profile.get("id_number") or "")
    key = f"task_type={task_type}|persona={persona}|policy={policy_id}|id={id_number}"
    return "fam_" + sha1(key).hexdigest()[:16]

