def stream2_row_to_messages(row):
    msgs = []
    for t in row["visible_history"]:          # 已经不含工具轮
        if t["role"] == "assistant":
            msgs.append({"role": "agent", "content": t["content"]})      # 不算损失
        elif t["role"] == "user":
            msgs.append({"role": "simulator", "content": t["content"]})  # 算损失
    msgs = _merge_consecutive_roles(msgs)
    if not msgs or msgs[0]["role"] != "agent":
        msgs.insert(0, {"role": "agent", "content": BOOTSTRAP_AGENT_PROMPT})
    msgs.append({"role": "simulator", "content": row["target_user_utterance"]})
    return msgs

async def rollout_spec(model, scenario, simulator, reward_clients, config):
    task = CanonicalTask.model_validate(scenario.task)
    sandbox = Sandbox(init_state=task.db_init_state, task_type=task.task_type)
    history = [{"role": "user", "content": task.opening_message}]
    terminated = "max_turns"
    metrics = {}
    for _ in range(config.max_turns):
        content = await generate(model, history)
        try:
            _, action = parse_analysis_action(content)
        except ParseError as exc:
            terminated = "hard_violation"          # 不是丢掉这条
            metrics = {"hard_violation_flag": True, "failure_class": "format_failure"}
            break
        if action.action_type in {"Finish", "Escalate", "FinishWithRefusal"}:
            terminated = action.action_type
            break
        if action.action_type == "Call_API":
            try:
                result = sandbox.execute(action.tool_name, action.tool_args)
            except UnknownToolError:
                terminated = "hard_violation"
                metrics = {"hard_violation_flag": True, "failure_class": "unknown_tool"}
                break
            history.append({"role": "observation", "content": json.dumps(result.data)})
            if is_hard_sandbox_result(result):
                terminated = "hard_violation"
                break
        elif action.action_type == "Ask_User":
            history.append({"role": "user", "content": await simulator.respond(task, history)})
    episode = EpisodeResult(..., terminated_by=terminated, metrics=metrics)
    breakdown = compute_reward(episode, task, ...)   # hard_violation → r_total = 0
    return episode, breakdown

