    if tool_name not in self.api_specs:
        raise UnknownToolError(tool_name)
    if tool_name not in self.policy_card.allowed_tools:
        return error_result(TOOL_NOT_ALLOWED)
    spec = self.api_specs[tool_name]
    if any(r.name not in args for r in spec.required_args):
        return error_result(MISSING_REQUIRED_ARG)
    for arg_spec in spec.required_args + spec.optional_args:
        if arg_spec.name in args:
            ok, reason = _validate_arg(args[arg_spec.name], arg_spec)
            if not ok:
                return error_result(INVALID_FORMAT, reason=reason)
    for pre in spec.preconditions:
        if not self.runtime_flags.get(pre, False):
            return error_result(PRECONDITION_NOT_MET)   # 不计数
    self._call_counter[tool_name] = self._call_counter.get(tool_name, 0) + 1
    inj = self._pop_injection(tool_name, self._call_counter[tool_name])
    if inj:
        return error_result(inj["error_code"], injected=True)
    res = self.tool_handlers[tool_name](self.db, args, copy.deepcopy(self._tool_call_log))
    if res.status == "ok":
        for post in spec.postconditions:
            self.runtime_flags[post] = True
    return res

