def assert_family_split_invariant(rows, split_map):
    buckets = {}
    for row in rows:
        buckets.setdefault(row["family_id"], set()).add(split_map[row["sample_id"]])
    leaked = {k: v for k, v in buckets.items() if len(v) > 1}
    if leaked:
        raise AssertionError(leaked)

