def _merge_consecutive_roles(msgs):
    out = [msgs[0]]
    for m in msgs[1:]:
        if m["role"] == out[-1]["role"]:
            out[-1]["content"] += "\n" + m["content"]
        else:
            out.append(m)
    return out

