def group_relative_advantage(rewards, group_id):
    # 项目 tokenize：A = (R - mean) / (std + 1e-6)
    adv = zeros_like(rewards)
    for g in unique(group_id):
        m = group_id == g
        r = rewards[m]
        std = r.std(unbiased=False)
        if r.numel() <= 1 or std == 0:
            adv[m] = 0.0
        else:
            adv[m] = (r - r.mean()) / (std + 1e-6)
    return adv

def should_keep_group(rewards, epsilon=1e-12):
    # 滤组门槛是 1e-12，不是优势分母
    return reward_variance(rewards) > epsilon

# 本项目调用：adv = group_relative_advantage(...) → cispo_loss(..., adv, ...)

def reinforce_loss(new_logp, advantages, mask):
    # new_logp: 当前策略对数概率，有梯度
    # advantages: 外来回报/基线，无梯度
    seq_logp = (new_logp * mask).sum(dim=-1)
    return -(advantages * seq_logp).mean()

def sequence_geometric_ratio(new_logp, old_logp, mask):
    length = mask.sum(dim=-1).clamp(min=1)
    mean_log_diff = ((new_logp - old_logp) * mask).sum(dim=-1) / length
    return exp(mean_log_diff)                    # 一句一个 s

def gspo_loss(new_logp, old_logp, advantages, mask, eps=0.2):
    # 本项目不用。advantages 仍是组相对优势
    s = sequence_geometric_ratio(new_logp, old_logp, mask)
    obj = min(s * advantages, clip(s, 1 - eps, 1 + eps) * advantages)
    return -obj.mean()

def dpo_loss(pi_w, ref_w, mask_w, pi_l, ref_l, mask_l, beta=0.1):
    # 全序列对数似然，没有旧对数概率，没有 A
    logp_w = (pi_w * mask_w).sum(-1) - (ref_w * mask_w).sum(-1)
    logp_l = (pi_l * mask_l).sum(-1) - (ref_l * mask_l).sum(-1)
    logits = beta * (logp_w - logp_l)
    return -log_sigmoid(logits).mean()
